values ((select id from public.parks where slug = 'weeki-wachee-springs-state-park'), 'notice', 'Buccaneer Bay schedule: the beach and swimming are open daily, but the water slides and lazy river run on Saturdays and Sundays only from Aug. 11 to Sept. 27, 2026 and are closed for the season beginning Sept. 28, 2026. The kiddie pool is closed for renovations. Once the park is full, no more tickets are sold and you cannot re-enter.', 'manual', 'https://www.floridastateparks.org/frequently-asked-questions', 'Minor', '2026-08-11T00:00:00-04:00'::timestamptz, null, '8e485e72d5269928d2c8bdc35152ae2b75370839', now(), now(), true, now())
on conflict ("hash") do update set "text" = excluded."text", "official_url" = excluded."official_url", "severity" = excluded."severity", "starts_at" = excluded."starts_at", "ends_at" = excluded."ends_at", "active" = excluded."active", "last_seen" = now(), "last_checked_at" = now();
insert into public.park_alerts ("park_id", "kind", "text", "source", "official_url", "severity", "starts_at", "ends_at", "hash", "first_seen", "last_seen", "active", "last_checked_at")
values ((select id from public.parks where slug = 'kelly-park-rock-springs'), 'notice', 'Park capacity: each morning 280 vehicles are allowed into Kelly Park, and an additional 50 vehicles are admitted after 1 p.m. with an afternoon parking pass - about 330 vehicles and an average of 1,350 visitors a day. On a typical summer day the park fills within an hour of opening. You must collect a pass in the morning when the park first hits capacity to get in at the 1 p.m. re-opening (one pass per car, first-come, first-served). The county web page and the information line, 407-254-1906, are updated when the park is full.', 'manual', 'https://www.ocfl.net/cultureparks/parks.aspx?d=22&m=dtlvw', 'Moderate', '2026-08-11T00:00:00-04:00'::timestamptz, null, '2851f24bc3a105e5cef9c2ff19156ecef1cda46d', now(), now(), true, now())
on conflict ("hash") do update set "text" = excluded."text", "official_url" = excluded."official_url", "severity" = excluded."severity", "starts_at" = excluded."starts_at", "ends_at" = excluded."ends_at", "active" = excluded."active", "last_seen" = now(), "last_checked_at" = now();
insert into public.park_alerts ("park_id", "kind", "text", "source", "official_url", "severity", "starts_at", "ends_at", "hash", "first_seen", "last_seen", "active", "last_checked_at")
values ((select id from public.parks where slug = 'lithia-springs-conservation-park'), 'closure', 'Hillsborough County announcement: "Due to high water levels and unsafe conditions, the spring is currently closed for swimming." The rest of Lithia Springs Conservation Park - campground, trails, playground and picnic areas - remains open. No reopening date has been given; the county page was last updated 10 September 2026.', 'manual', 'https://hcfl.gov/locations/lithia-springs-park', 'Severe', '2026-09-10T00:00:00-04:00'::timestamptz, null, '11fe5cfb67b878780ea34ebb90288d450c4b930e', now(), now(), true, now())
on conflict ("hash") do update set "text" = excluded."text", "official_url" = excluded."official_url", "severity" = excluded."severity", "starts_at" = excluded."starts_at", "ends_at" = excluded."ends_at", "active" = excluded."active", "last_seen" = now(), "last_checked_at" = now();
insert into public.park_alerts ("park_id", "kind", "text", "source", "official_url", "severity", "starts_at", "ends_at", "hash", "first_seen", "last_seen", "active", "last_checked_at")
values ((select id from public.parks where slug = 'cypress-spring'), 'notice', 'Northwest Florida Water Management District, 8 January 2026: contractors have begun the Cypress Spring shoreline restoration and protection project, adding shoreline stabilisation, boardwalks and steps at the entry and exit points. While the work continues, access to the shoreline may be restricted; the spring itself remains accessible by watercraft. The District said the work was expected to last several months and has not posted a completion notice.', 'manual', 'https://nwfwater.com/restoration-work-begins-at-cypress-spring/', 'Minor', '2026-01-08T00:00:00-05:00'::timestamptz, null, '94087eaa1ca0f61c208b335c70f67fe3f1358813', now(), now(), true, now())
on conflict ("hash") do update set "text" = excluded."text", "official_url" = excluded."official_url", "severity" = excluded."severity", "starts_at" = excluded."starts_at", "ends_at" = excluded."ends_at", "active" = excluded."active", "last_seen" = now(), "last_checked_at" = now();

